def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'D' if history[0][1] == 'D' else 'C'
    if n >= 100:
        return 'C'

    opp_c = 0
    my_def = 0
    for a, b in history:
        if b == 'C':
            opp_c += 1
        if a == 'D':
            my_def += 1
    opp_d = n - opp_c

    last_me, last_opp = history[-1]
    rounds_left = 100 - n

    def_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            def_streak += 1
        else:
            break

    recent_len = min(10, n)
    recent_opp = sum(1 for i in range(n - recent_len, n) if history[i][1] == 'C') / recent_len

    if rounds_left <= 1:
        return 'D'

    if opp_d == 0:
        if my_def > 0:
            return 'D'
        if rounds_left <= 2:
            return 'D'
        return 'C'

    if rounds_left <= 2:
        if last_opp == 'C' and recent_opp > 0.4:
            return 'D'
        if last_opp == 'D':
            return 'D'
        return 'C'

    if rounds_left <= 6:
        if recent_opp >= 0.7:
            return 'C'
        if recent_opp <= 0.3:
            return 'D'
        if last_opp == 'D':
            return 'D'
        return 'C'

    if last_opp == 'D':
        if def_streak >= 3 and opp_c > 0:
            if def_streak == 3:
                return 'C'
            if rng.random() < 0.15:
                return 'C'
        if def_streak >= 2:
            return 'D'
        if recent_opp >= 0.55:
            return 'C'
        return 'D'

    if last_me == 'D':
        return 'C'

    if recent_opp >= 0.5:
        return 'C'

    if recent_opp < 0.35:
        if opp_c < opp_d:
            return 'D'
        if rng.random() < 0.35:
            return 'D'
        return 'C'

    return 'C'
